#import "LQSMonet.h"
#import "MCUHct.h"
#import "MCUQuantizerCelebi.h"
#import "MCUQuantizerResult.h"
#import "MCUTonalPalette.h"
#import "LQSTheme.h"

static const int kGoogleBlue = (int)0xFF1B6EF3; // ColorScheme.GOOGLE_BLUE
static const double kMinChroma = 5;             // ColorScheme.MIN_CHROMA
static const double kAccent1Chroma = 48;        // ColorScheme.ACCENT1_CHROMA

@implementation LQSMonet

#pragma mark - Colour table

// Resources/monet_table.bin, generated by the original libmonet Java on s8build
// (Gen.java): [style 4][hue 0..359][dark 2][token N] little-endian ARGB, seed =
// Hct.from(hue, 100, 80), SPEC_2026, PHONE. Exact for freeform colours; wallpaper
// seeds are looked up by their HCT hue (assumption: chroma/tone of the seed and
// further seeds are ignored).
static NSData *gTable;
static NSArray<NSString *> *gTokens;

static void LoadTable(void) {
    if (gTable) return;
    NSString *root = [LQSTheme resourceRoot];
    gTable = [NSData dataWithContentsOfFile:[root stringByAppendingPathComponent:@"monet_table.bin"] options:NSDataReadingMappedIfSafe error:nil];
    NSString *t = [NSString stringWithContentsOfFile:[root stringByAppendingPathComponent:@"monet_tokens.txt"] encoding:NSUTF8StringEncoding error:nil];
    gTokens = [[t stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet] componentsSeparatedByString:@"\n"];
}

static NSInteger StyleIndex(NSString *style) {
    NSUInteger i = [@[@"neutral", @"tonal_spot", @"vibrant", @"expressive"] indexOfObject:style];
    return i == NSNotFound ? 1 : (NSInteger)i;
}

static const uint32_t *Row(NSString *style, NSArray<NSNumber *> *seeds, BOOL dark) {
    LoadTable();
    NSUInteger n = gTokens.count;
    if (!gTable || !n) return NULL;
    int seed = seeds.count ? seeds.firstObject.intValue : kGoogleBlue;
    MCUHct *h = [MCUHct fromInt:seed];
    if (seed == 0 || [h getChroma] < kMinChroma) h = [MCUHct fromInt:kGoogleBlue]; // ColorScheme: grey seeds -> Google Blue
    int hue = ((int)floor([h getHue] + 0.5)) % 360;
    size_t idx = (((size_t)StyleIndex(style) * 360 + hue) * 2 + (dark ? 1 : 0)) * n;
    if ((idx + n) * 4 > gTable.length) return NULL;
    return (const uint32_t *)gTable.bytes + idx;
}

+ (NSDictionary<NSString *, NSNumber *> *)schemeForSeeds:(NSArray<NSNumber *> *)seeds style:(NSString *)style dark:(BOOL)dark {
    const uint32_t *r = Row(style, seeds, dark);
    NSMutableDictionary *out = [NSMutableDictionary dictionary];
    if (!r) return out;
    for (NSUInteger i = 0; i < gTokens.count; i++) out[gTokens[i]] = @(CFSwapInt32LittleToHost(r[i]));
    return out;
}

+ (NSDictionary<NSString *, NSString *> *)systemColorsForSeeds:(NSArray<NSNumber *> *)seeds style:(NSString *)style {
    NSMutableDictionary *out = [NSMutableDictionary dictionary];
    for (int d = 0; d < 2; d++) {
        NSDictionary *s = [self schemeForSeeds:seeds style:style dark:d == 1];
        for (NSString *k in s) {
            if ([k isEqualToString:@"swatch"]) continue;
            unsigned v = [s[k] unsignedIntValue];
            NSString *hex = ((v >> 24) & 0xff) == 0xff ? [NSString stringWithFormat:@"#%06X", v & 0xffffff] : [NSString stringWithFormat:@"#%08X", v];
            out[[NSString stringWithFormat:@"system_%@_%@", k, d ? @"dark" : @"light"]] = hex;
        }
    }
    return out;
}

+ (int)freeformSeedForHue:(double)hue { return [[MCUHct from:hue chroma:100 tone:80] toInt]; }
+ (double)hueOfColor:(int)argb { return [[MCUHct fromInt:argb] getHue]; }

// getLightOneOrTwoColorPreview: accent1 shade 450 light / 200 dark ("swatch" in the table).
+ (int)swatchColorForSeed:(int)seed style:(NSString *)style dark:(BOOL)dark {
    return [[self schemeForSeeds:@[@(seed)] style:style dark:dark][@"swatch"] intValue];
}

#pragma mark - Wallpaper colours

static int WrapDegrees(int d) { return d < 0 ? (d % 360) + 360 : (d >= 360 ? d % 360 : d); }
static double HueDiff(double a, double b) { double d = fabs(a - b); return d > 180.0f ? 360.0f - d : d; }
static double Score(MCUHct *h, double proportion) {
    double proportionScore = 0.7 * 100.0 * proportion;
    double chromaScore = [h getChroma] < kAccent1Chroma ? 0.1 * ([h getChroma] - kAccent1Chroma) : 0.3 * ([h getChroma] - kAccent1Chroma);
    return chromaScore + proportionScore;
}

// ColorScheme.getSeedColors(wallpaperColors, filter = true).
+ (NSArray<NSNumber *> *)seedColorsFromPopulation:(NSDictionary<NSNumber *, NSNumber *> *)pop {
    double total = 0;
    for (NSNumber *k in pop) total += [pop[k] intValue];
    if (total == 0) return @[@(kGoogleBlue)];
    NSMutableDictionary<NSNumber *, MCUHct *> *hct = [NSMutableDictionary dictionary];
    for (NSNumber *k in pop) hct[k] = [MCUHct fromInt:k.intValue];
    double hues[360] = {0};
    for (NSNumber *k in pop) {
        MCUHct *h = hct[k];
        int hue = (int)((long)floor([h getHue] + 0.5) % 360);
        if ([h getChroma] <= kMinChroma) continue;
        hues[hue] += [pop[k] intValue] / total;
    }
    NSMutableDictionary<NSNumber *, NSNumber *> *hueProp = [NSMutableDictionary dictionary];
    for (NSNumber *k in pop) {
        int hue = (int)(long)floor([hct[k] getHue] + 0.5);
        double p = 0;
        for (int i = hue - 15; i <= hue + 15; i++) p += hues[WrapDegrees(i)];
        hueProp[k] = @(p);
    }
    NSMutableArray<NSArray *> *scored = [NSMutableArray array]; // @[color, score]
    for (NSNumber *k in pop) {
        if ([hct[k] getChroma] < kMinChroma || [hueProp[k] doubleValue] <= 0.01) continue;
        [scored addObject:@[k, @(Score(hct[k], [hueProp[k] doubleValue]))]];
    }
    [scored sortWithOptions:NSSortStable usingComparator:^NSComparisonResult(NSArray *a, NSArray *b) { return [b[1] compare:a[1]]; }];
    NSMutableArray<NSNumber *> *seeds = [NSMutableArray array];
    for (int i = 90; i >= 15; i--) {
        [seeds removeAllObjects];
        for (NSArray *e in scored) {
            BOOL near = NO;
            for (NSNumber *s in seeds) if (HueDiff([hct[e[0]] getHue], [hct[s] getHue]) < i) { near = YES; break; }
            if (near) continue;
            [seeds addObject:e[0]];
            if (seeds.count >= 4) break;
        }
        if (seeds.count) break;
    }
    if (!seeds.count) [seeds addObject:@(kGoogleBlue)];
    return seeds;
}

// WallpaperColors.fromBitmap: scale (no filtering) to <= 112x112 area, Celebi with
// max(5, min(128, area / 16)) colours, population by colour.
+ (NSArray<NSNumber *> *)seedColorsFromImage:(UIImage *)image {
    CGImageRef cg = image.CGImage;
    if (!cg) return @[@(kGoogleBlue)];
    size_t w0 = CGImageGetWidth(cg), h0 = CGImageGetHeight(cg);
    double area = (double)w0 * h0, maxArea = 112.0 * 112.0, scale = area > maxArea ? sqrt(maxArea / area) : 1;
    size_t w = MAX(1, (size_t)(w0 * scale)), h = MAX(1, (size_t)(h0 * scale));
    uint32_t *buf = calloc(w * h, 4);
    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
    CGContextRef ctx = CGBitmapContextCreate(buf, w, h, 8, w * 4, cs, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little);
    CGContextSetInterpolationQuality(ctx, kCGInterpolationNone);
    CGContextDrawImage(ctx, CGRectMake(0, 0, w, h), cg);
    NSMutableArray<NSNumber *> *px = [NSMutableArray arrayWithCapacity:w * h];
    for (size_t i = 0; i < w * h; i++) px[i] = @((int)(buf[i] | 0xFF000000u)); // BGRA little-endian = ARGB int
    CGContextRelease(ctx);
    CGColorSpaceRelease(cs);
    free(buf);
    int colors = (int)MAX(5, MIN(128, (w * h) / 16));
    MCUQuantizerResult *q = [MCUQuantizerCelebi quantize:px maxColors:colors];
    return [self seedColorsFromPopulation:q.colorToCount];
}

@end
